<?php require_once __DIR__ . '/_migration_helpers.php'; $xtreampiPageScripts = ['assets/xtreampi/archive.js']; $xtreampiIsRecordings = is_array($rRecordings ?? null); $xtreampiItems = $xtreampiIsRecordings ? $rRecordings : (is_array($rArchive ?? null) ? $rArchive : []); $xtreampiStreamId = (int) (($rStream['id'] ?? 0)); ?>
<section class="sc-archive" data-sc-archive data-stream-id="<?php echo $xtreampiStreamId; ?>" data-recordings="<?php echo $xtreampiIsRecordings ? '1' : '0'; ?>">
    <div class="sc-page-heading"><div><p class="sc-eyebrow">Playback and recording</p><h1><?php echo $xtreampiIsRecordings ? 'Recordings' : sc_m_escape(($rStream['stream_display_name'] ?? 'Stream') . ' · TV Archive'); ?></h1></div><?php if ($xtreampiIsRecordings): ?><a class="sc-button sc-button-primary" href="record">Schedule recording</a><?php endif; ?></div>
    <section class="sc-data-panel"><div class="sc-table-scroll"><table class="sc-data-table"><thead><tr><th>ID</th><th>Date</th><th>Duration</th><th>Title</th><th>Status</th><th>Player</th><th>Actions</th></tr></thead><tbody><?php if (!$xtreampiItems): ?><tr><td class="sc-table-state" colspan="7">No recordings or archive entries.</td></tr><?php else: foreach ($xtreampiItems as $xtreampiItem): $start = (int) ($xtreampiItem['start'] ?? 0); $end = (int) ($xtreampiItem['end'] ?? $start); $duration = max(0, $end - $start); $xtreampiStatusCode = (int) ($xtreampiItem['status'] ?? 3); if ($xtreampiIsRecordings && $xtreampiStatusCode === 0 && empty($xtreampiItem['archive']) && $end < time()) $xtreampiStatusCode = 3; $status = $xtreampiIsRecordings ? ($xtreampiStatusCode === 2 ? 'Complete' : ($xtreampiStatusCode === 1 ? 'Recording' : ($xtreampiStatusCode === 0 ? 'Waiting' : 'Failed'))) : (!empty($xtreampiItem['in_progress']) ? 'In progress' : (!empty($xtreampiItem['complete']) ? 'Complete' : 'Incomplete')); ?><tr data-sc-archive-row data-recording-id="<?php echo (int) ($xtreampiItem['id'] ?? 0); ?>" data-created-id="<?php echo (int) ($xtreampiItem['created_id'] ?? 0); ?>" data-start="<?php echo $start; ?>" data-duration="<?php echo max(1, (int) floor($duration / 60)); ?>"><td><?php echo (int) ($xtreampiItem['id'] ?? 0); ?></td><td><?php echo sc_m_escape($start ? date(($rSettings['date_format'] ?? 'Y-m-d') . ' H:i', $start) : '—'); ?></td><td><?php echo sprintf('%02dh %02dm', (int) floor($duration / 3600), (int) floor(($duration % 3600) / 60)); ?></td><td><?php echo sc_m_escape($xtreampiItem['title'] ?? ''); ?></td><td><?php echo $status; ?></td><td><button type="button" class="sc-row-action" data-sc-archive-play<?php echo (!$xtreampiIsRecordings && !empty($xtreampiItem['in_progress'])) ? '' : ''; ?>>Play</button></td><td><?php if ($xtreampiIsRecordings): ?><?php if (!empty($xtreampiItem['created_id'])): ?><a class="sc-row-action" href="stream_view?id=<?php echo (int) $xtreampiItem['created_id']; ?>">View</a><?php endif; ?><button type="button" class="sc-row-action" data-sc-archive-delete>Delete</button><?php else: ?><a class="sc-row-action" href="record?archive=<?php echo rawurlencode(base64_encode(json_encode(array_merge($xtreampiItem, ['stream_id' => $xtreampiStreamId])))); ?>">Record</a><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section><dialog data-sc-archive-player><button type="button" data-sc-archive-close>Close</button><iframe title="Player" allowfullscreen></iframe></dialog>
</section>
